<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content"><div class="panel_s"><div class="panel-body"><h4><i class="fa-solid fa-address-book text-info"></i> Contact Search</h4><form method="get"><div class="input-group"><input name="q" value="<?= e($q); ?>" class="form-control" placeholder="Name, company, email, or phone"><span class="input-group-btn"><button class="btn btn-info">Search</button></span></div></form><?php if($q!==''){ ?><div class="table-responsive mtop20"><table class="table table-striped"><thead><tr><th>Name</th><th>Company</th><th>Email</th><th>Phone</th></tr></thead><tbody><?php foreach($contacts as $c){ ?><tr><td><a href="<?= admin_url('clients/client/'.$c->userid.'?group=contacts'); ?>"><?= e(trim($c->firstname.' '.$c->lastname)); ?></a></td><td><?= e($c->company); ?></td><td><?= e($c->email); ?></td><td><?= e($c->phonenumber); ?></td></tr><?php } if(!$contacts){ ?><tr><td colspan="4">No contacts found.</td></tr><?php } ?></tbody></table></div><?php } ?></div></div></div></div><?php init_tail(); ?>